<!--
 * 审计日志（列表页 / 只读）
 *
 * @path apps\cronjob-web\src\views\audit-log\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 审计日志（P1-操作审计闭环）
 * <p>消费后端契约 auditLog.ts（auto-generated by bash/gen-contract.py）：
 * page 分页查询审计日志。
 * 布局：顶部筛选栏（操作类型 / 操作人 / 时间范围）+ 审计日志分页列表 + 详情抽屉。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page } from '@ydsz/common-ui';

import { ElButton, ElDescriptions, ElDescriptionsItem, ElDrawer, ElTag } from 'element-plus';
import { h, ref } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { page } from '#/api/auditLog';
import type { AuditLogVO } from '#/api/models';

import { createLogger } from '@ydsz-core/shared/utils';

const logger = createLogger('cronjob-audit-log');

defineOptions({ name: 'AuditLogManagement' });

// ==================== 详情抽屉 ====================

/** 详情抽屉可见性 */
const isDetailVisible = ref(false);
/** 当前查看的审计记录 */
const detailRecord = ref<AuditLogVO | null>(null);

/** 打开详情抽屉 */
function handleViewDetail(row: AuditLogVO): void {
  detailRecord.value = row;
  isDetailVisible.value = true;
}

// ==================== 工具方法 ====================

/** 操作行为中文映射 */
function translateAction(action?: number): string {
  const map: Record<number, string> = {
    1: '新增',
    2: '修改',
    3: '删除',
    4: '暂停',
    5: '恢复',
    6: '触发',
    7: '导入',
    8: '导出',
  };
  return map[action ?? 0] ?? String(action ?? '-');
}

/** 操作模块中文映射 */
function translateAuditType(auditType?: number): string {
  const map: Record<number, string> = {
    1: '任务管理',
    2: 'DAG管理',
    3: '告警规则',
    4: '连接器',
    5: '系统配置',
  };
  return map[auditType ?? 0] ?? String(auditType ?? '-');
}

/** 执行耗时格式化 */
function formatCostTime(costTime?: number): string {
  if (costTime === undefined || costTime === null) return '-';
  if (costTime < 1000) return `${costTime} ms`;
  return `${(costTime / 1000).toFixed(2)} s`;
}

// ==================== Vxe 表格 ====================

const gridOptions: VxeTableGridOptions<AuditLogVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    {
      field: 'auditType',
      title: '模块',
      width: 110,
      slots: {
        default: ({ row }) => {
          const item = row as AuditLogVO;
          return h(ElTag, { size: 'small', type: 'info' }, () => translateAuditType(item.auditType));
        },
      },
    },
    {
      field: 'action',
      title: '操作行为',
      width: 100,
      slots: {
        default: ({ row }) => {
          const item = row as AuditLogVO;
          return h(ElTag, { size: 'small' }, () => translateAction(item.action));
        },
      },
    },
    { field: 'content', title: '操作内容', minWidth: 200, showOverflow: true },
    { field: 'businessNo', title: '业务流水号', width: 140 },
    { field: 'operatorName', title: '操作人', width: 100 },
    { field: 'ipAddress', title: 'IP 地址', width: 130 },
    { field: 'operationTime', title: '操作时间', width: 170 },
    {
      field: 'costTime',
      title: '耗时',
      width: 100,
      slots: {
        default: ({ row }) => {
          const item = row as AuditLogVO;
          return h('span', null, formatCostTime(item.costTime));
        },
      },
    },
    {
      field: 'actioncol',
      title: '操作',
      width: 80,
      fixed: 'right',
      slots: {
        default: ({ row }) => {
          const item = row as AuditLogVO;
          return h(
            ElButton,
            { size: 'small', link: true, type: 'primary', onClick: () => handleViewDetail(item) },
            () => '详情',
          );
        },
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async ({ page: pageInfo }, formValues) => {
        const timeRange = formValues?.startTime as unknown;
        let startTime: string | undefined;
        let endTime: string | undefined;
        if (Array.isArray(timeRange) && timeRange.length === 2) {
          startTime = timeRange[0] as string;
          endTime = timeRange[1] as string;
        }
        const res = await page({
          pageNum: pageInfo.currentPage,
          size: pageInfo.pageSize,
          action: formValues?.action as number | undefined,
          operatorName: formValues?.operatorName as string | undefined,
          startTime,
          endTime,
        });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      {
        field: 'action',
        title: '操作行为',
        itemRender: {
          name: 'Select',
          props: {
            clearable: true,
            options: [
              { label: '新增', value: 1 },
              { label: '修改', value: 2 },
              { label: '删除', value: 3 },
              { label: '暂停', value: 4 },
              { label: '恢复', value: 5 },
              { label: '触发', value: 6 },
            ],
          },
        },
      },
      {
        field: 'operatorName',
        title: '操作人',
        itemRender: { name: 'Input', props: { placeholder: '操作人姓名' } },
      },
      {
        field: 'startTime',
        title: '时间范围',
        itemRender: {
          name: 'DatePicker',
          props: {
            type: 'daterange',
            startPlaceholder: '开始日期',
            endPlaceholder: '结束日期',
            valueFormat: 'YYYY-MM-DD',
          },
        },
      },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });
</script>

<template>
  <Page auto-content-height>
    <Grid table-title="审计日志" />

    <!-- 详情抽屉 -->
    <ElDrawer v-model="isDetailVisible" title="审计日志详情" size="600px">
      <template v-if="detailRecord">
        <ElDescriptions :column="2" border size="small">
          <ElDescriptionsItem label="模块">
            <ElTag size="small" type="info">{{ translateAuditType(detailRecord.auditType) }}</ElTag>
          </ElDescriptionsItem>
          <ElDescriptionsItem label="操作行为">
            <ElTag size="small">{{ translateAction(detailRecord.action) }}</ElTag>
          </ElDescriptionsItem>
          <ElDescriptionsItem label="操作内容" :span="2">
            {{ detailRecord.content ?? '-' }}
          </ElDescriptionsItem>
          <ElDescriptionsItem label="业务流水号">{{ detailRecord.businessNo ?? '-' }}</ElDescriptionsItem>
          <ElDescriptionsItem label="操作人">{{ detailRecord.operatorName ?? '-' }}</ElDescriptionsItem>
          <ElDescriptionsItem label="IP 地址">{{ detailRecord.ipAddress ?? '-' }}</ElDescriptionsItem>
          <ElDescriptionsItem label="操作时间">{{ detailRecord.operationTime ?? '-' }}</ElDescriptionsItem>
          <ElDescriptionsItem label="执行耗时">
            {{ formatCostTime(detailRecord.costTime) }}
          </ElDescriptionsItem>
          <ElDescriptionsItem label="TraceId">{{ detailRecord.traceId ?? '-' }}</ElDescriptionsItem>
        </ElDescriptions>
      </template>
    </ElDrawer>
  </Page>
</template>
